import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.25.0";
import { z as z3 } from "npm:zod@^3.25.76";
var get_request_default = defineTool3({
  name: "get_request",
  title: "Get request with items",
  description: "Fetch one material request by id or request number, including all of its line items.",
  inputSchema: {
    request_id: z3.string().optional().describe("Request id (uuid)."),
    request_no: z3.string().optional().describe("Request/document number, e.g. RMR-0012.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ request_id, request_no }, ctx) => {
    if (!ctx.isAuthenticated()) return errorResult("Not authenticated");
    if (!request_id && !request_no)
      return errorResult("Provide either request_id or request_no.");
    const client = supabaseForUser(ctx);
    let query = client.from("requests").select("*").limit(1);
    query = request_id ? query.eq("id", request_id) : query.eq("request_no", request_no);
    const { data: requests, error } = await query;
    if (error) return errorResult(error.message);
    const request = requests?.[0];
    if (!request) return errorResult("Request not found.");
    const { data: items, error: itemsError } = await client.from("request_items").select("*").eq("request_id", request.id).order("sort_order", { ascending: true }).order("created_at", { ascending: true });
    if (itemsError) return errorResult(itemsError.message);
    return textResult({ request, items: items ?? [] });
  }
});

