// src/lib/mcp/tools/add-catalog-item.ts
import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@0.25.0";
import { z as z6 } from "npm:zod@^3.25.76";
var add_catalog_item_default = defineTool6({
  name: "add_catalog_item",
  title: "Add item to catalog",
  description: "Add a new item (item code, description, unit of measure) to the item master catalog. Search first to avoid duplicates.",
  inputSchema: {
    item_code: z6.string().describe("Item code, e.g. TRM-1042."),
    description: z6.string().describe("Standardized item description."),
    uom: z6.string().optional().describe("Unit of measure, e.g. PCS, MTR, YDS.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async ({ item_code, description, uom }, ctx) => {
    if (!ctx.isAuthenticated()) return errorResult("Not authenticated");
    const client = supabaseForUser(ctx);
    const code = item_code.trim();
    const desc = description.trim();
    if (!code || !desc) return errorResult("item_code and description are required.");
    const { data: existing, error: lookupError } = await client.from("material_catalog").select("id, item_code, description, uom");
    if (lookupError) return errorResult(lookupError.message);
    const norm = (v) => v.trim().toLowerCase().replace(/\s+/g, " ");
    const duplicate = (existing ?? []).find(
      (row) => norm(row.item_code ?? "") === norm(code) && norm(row.description ?? "") === norm(desc)
    );
    if (duplicate) return textResult({ created: false, reason: "duplicate", item: duplicate });
    const { data, error } = await client.from("material_catalog").insert({ item_code: code, description: desc, uom: uom?.trim() || "PCS", created_by: ctx.getUserId() }).select().single();
    if (error) return errorResult(error.message);
    return textResult({ created: true, item: data });
  }
});

